DECLARE receipt jsonb := '{"mappings": [{"id": 79, "md5": "173d1f709ed6bcad6d0131bf1d5c5253", "before": {"id": 79, "label": "đã xem", "is_active": true, "is_delete": false, "status_id": null, "created_at": "2026-07-15T15:14:06.141048+00:00", "sort_order": 40, "updated_at": "2026-10-03T04:32:18.895474+00:00", "action_code": "email_send", "description": "Loại chiến dịch: email_send. Phạm vi: chỉ hành động email_send. Trạng thái: đã xem. Email tracking nhận sự kiện mở/xem; tín hiệu tracking, không chứng minh chắc chắn người thật đã đọc nội dung. status_id=NULL: chưa gắn nhóm ngữ nghĩa auto_status; không tự điền ID theo suy đoán. Đây là danh mục lựa chọn Automation, không chứng minh đã có lượt chạy phát ra trạng thái. So khớp status_value không phân biệt hoa/thường; action_code NULL là wildcard. Dòng có sẵn trước v347, giữ nguyên ID/điều kiện/trạng thái. Không giả định chuỗi lịch sử còn được mọi phiên bản runtime phát ra. Mô tả cho agent, không điều khiển runtime.", "status_value": "đã xem", "campaign_action_id": "email_send"}}, {"id": 80, "md5": "e7398dfca171d82ff3cc8fb7b68e2e7f", "before": {"id": 80, "label": "đã click", "is_active": true, "is_delete": false, "status_id": null, "created_at": "2026-07-15T15:14:06.141048+00:00", "sort_order": 50, "updated_at": "2026-09-22T11:16:10.187991+00:00", "action_code": "email_send", "description": "Loại chiến dịch: email_send. Phạm vi: chỉ hành động email_send. Trạng thái: đã click. Email tracking nhận sự kiện click liên kết; không suy ra chuyển đổi hoặc danh tính người click. status_id=NULL: chưa gắn nhóm ngữ nghĩa auto_status; không tự điền ID theo suy đoán. Đây là danh mục lựa chọn Automation, không chứng minh đã có lượt chạy phát ra trạng thái. So khớp status_value không phân biệt hoa/thường; action_code NULL là wildcard. Dòng có sẵn trước v347, giữ nguyên ID/điều kiện/trạng thái. Không giả định chuỗi lịch sử còn được mọi phiên bản runtime phát ra. Mô tả cho agent, không điều khiển runtime.", "status_value": "đã click", "cam